<script setup lang="ts">
type Dtr={BatchID:number,AgencyID?:number,AgencyName:string,ClientName:string,SiteName:string,PeriodStart:string,PeriodEnd:string}
type Row={EmployeeID:number,EmployeeNumber:string|null,EmployeeName:string,DeploymentType:'Regular'|'Reliever',Days:number,PositionName?:string,[key:string]:any}
type Shift={ShiftCodeID:number,ShiftCode:string,ShiftName:string,ShiftType:'Day'|'Night'|'Split'|'Flexible',TimeIn:string,TimeOut:string,RegularHours:number,RegularOTCap:number,NDEnabled?:number|boolean,NDStartTime?:string|null,NDEndTime?:string|null}
const props=defineProps<{dtr:Dtr}>()
const emit=defineEmits<{close:[],changed:[]}>()
const hourFields=[['RegularHours','Regular hours'],['OTHours','Regular OT'],['OTExtHours','OT extension'],['NightDiffHours','Night differential'],['RestDayHours','Rest day hours'],['RestDayOTHours','Rest day OT'],['LegalHolidayHours','Legal holiday hours'],['LegalHolidayOTHours','Legal holiday OT'],['RestDayLegalHolidayHours','Rest day legal holiday'],['RestDayLegalHolidayOTHours','Rest day legal holiday OT'],['SpecialHolidayHours','Special holiday hours'],['SpecialHolidayOTHours','Special holiday OT'],['RestDaySpecialHolidayHours','Rest day special holiday'],['RestDaySpecialHolidayOTHours','Rest day special holiday OT'],['BreakHours','Break hours']] as const
const summaryFields=[['RegularHours','Regular'],['OTHours','Regular OT'],['OTExtHours','OT ext'],['NightDiffHours','Night diff'],['RestDayHours','Rest day'],['LateHours','Late'],['UndertimeHours','Undertime']] as const
const rows=ref<Row[]>([]),attendanceRows=ref<any[]>([]),shifts=ref<Shift[]>([]),search=ref(''),applied=ref(''),picker=ref(false),employeeSearch=ref(''),employees=ref<any[]>([]),selectedType=ref<'Regular'|'Reliever'>('Regular'),saving=ref(false),typeSaving=ref<number|null>(null),error=ref('')
const dayOpen=ref(false),dayForm=ref<any>(null),selectedRow=ref<Row|null>(null),batchOpen=ref(false),batchEmployee=ref<Row|null>(null),batchShift=ref(''),batchShiftSearch=ref(''),batchSuggestionsOpen=ref(false)
const visibleRows=computed(()=>{const q=applied.value.toLowerCase();return !q?rows.value:rows.value.filter(r=>(String(r.EmployeeID)+' '+(r.EmployeeNumber||'')+' '+r.EmployeeName).toLowerCase().includes(q))})
const attendanceMap=computed(()=>new Map(attendanceRows.value.map(item=>[String(item.EmployeeID)+':'+String(item.AttendanceDate).slice(0,10),item])))
const totals=computed(()=>Object.fromEntries(summaryFields.map(([key])=>[key,attendanceRows.value.reduce((sum,row)=>sum+Number(row[key]||0),0)])))
const visibleBatchShifts=computed(()=>{const query=batchShiftSearch.value.trim().toLowerCase();return !query?shifts.value:shifts.value.filter(shift=>(shift.ShiftCode+' '+shift.ShiftName+' '+shift.ShiftType).toLowerCase().includes(query))})
const selectedBatchShift=computed(()=>shifts.value.find(shift=>String(shift.ShiftCodeID)===String(batchShift.value))||null)
function dateOnly(value:string){return String(value).slice(0,10)}
function dayLabel(value:string){return new Date(dateOnly(value)+'T00:00:00').toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'})}
function dates(){const result:string[]=[];for(let d=new Date(dateOnly(props.dtr.PeriodStart)+'T00:00:00');d<=new Date(dateOnly(props.dtr.PeriodEnd)+'T00:00:00');d.setDate(d.getDate()+1))result.push(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'));return result}
function entry(row:Row,date:string){return attendanceMap.value.get(String(row.EmployeeID)+':'+date)}
function formatNumber(value:any){return Number(value||0).toFixed(2)}
function totalDays(row:Row){return attendanceRows.value.filter(item=>item.EmployeeID===row.EmployeeID&&String(item.AttendanceStatus)!=='Absent').length}
function shiftTag(row:Row){const labels:{[key:string]:string}={Day:'DS',Night:'NS',Split:'SS',Flexible:'FX'};const tags=[...new Set(attendanceRows.value.filter(item=>item.EmployeeID===row.EmployeeID&&item.ShiftType).map(item=>labels[item.ShiftType]||item.ShiftType))];return tags.length?tags.join('/'):'-'}
function cellText(record:any){if(!record)return '-';if(record.AttendanceStatus==='Absent')return 'ABS';if(record.AttendanceStatus==='Rest Day')return 'RD';if(record.AttendanceStatus==='On-Leave')return 'LEAVE';const regular=Number(record.RegularHours||0),rest=Number(record.RestDayHours||0),holiday=Number(record.LegalHolidayHours||0)+Number(record.SpecialHolidayHours||0);return regular||rest||holiday?formatNumber(regular||rest||holiday):'0.00'}
function cellSub(record:any){if(!record)return 'Click to add';const ot=Number(record.OTHours||0)+Number(record.OTExtHours||0);return ot?formatNumber(ot):record.ShiftCode||record.AttendanceStatus}
function blankDay(row:Row,date:string){const item:any={EmployeeID:row.EmployeeID,AttendanceDate:date,ShiftCodeID:'',AttendanceStatus:'Present',AttendanceType:row.DeploymentType||'Regular',TimeIn:'',TimeOut:'',Remarks:'',LateHours:0,UndertimeHours:0,LateMinutes:0,UndertimeMinutes:0};hourFields.forEach(([key])=>item[key]=0);return item}
function nightDiffHours(timeIn:any,timeOut:any,shift:Shift){if(!shift.NDEnabled||!shift.NDStartTime||!shift.NDEndTime||!timeIn||!timeOut)return 0;const workStart=new Date(String(timeIn).replace(' ','T')),workEnd=new Date(String(timeOut).replace(' ','T'));if(Number.isNaN(workStart.getTime())||Number.isNaN(workEnd.getTime())||workEnd<=workStart)return 0;const startClock=String(shift.NDStartTime).slice(0,5),endClock=String(shift.NDEndTime).slice(0,5),cursor=new Date(workStart);cursor.setHours(0,0,0,0);cursor.setDate(cursor.getDate()-1);let milliseconds=0;while(cursor<=workEnd){const dateValue=cursor.getFullYear()+'-'+String(cursor.getMonth()+1).padStart(2,'0')+'-'+String(cursor.getDate()).padStart(2,'0'),windowStart=new Date(dateValue+'T'+startClock),windowEnd=new Date(dateValue+'T'+endClock);if(endClock<=startClock)windowEnd.setDate(windowEnd.getDate()+1);const from=Math.max(workStart.getTime(),windowStart.getTime()),to=Math.min(workEnd.getTime(),windowEnd.getTime());if(to>from)milliseconds+=to-from;cursor.setDate(cursor.getDate()+1)}return Math.round(milliseconds/3600000*100)/100}
function toInputDateTime(value:any){return value?String(value).replace('T',' ').slice(0,16):''}
async function load(){try{const result=await $fetch<any>('/api/attendance/dtr/'+props.dtr.BatchID+'/records');rows.value=result.records||[];attendanceRows.value=result.attendanceRows||[];shifts.value=result.shifts||[];if(!shifts.value.length){const fallback=await $fetch<any>('/api/organization/shift-code');const agencyId=Number(result.batch?.AgencyID||props.dtr.AgencyID||0);shifts.value=(fallback.items||[]).filter((shift:any)=>shift.Status==='Active'&&Number(shift.AgencyID)===agencyId)}if(!shifts.value.length)error.value='No active shift code is available for this DTR agency. Add or activate one under Shift Codes.'}catch(e:any){error.value=e?.data?.statusMessage||'Unable to load DTR attendance.'}}
async function findEmployees(){try{const result=await $fetch<any>('/api/attendance/dtr/'+props.dtr.BatchID+'/employees',{query:employeeSearch.value?{search:employeeSearch.value}:undefined});employees.value=result.employees||[]}catch(e:any){error.value=e?.data?.statusMessage||'Unable to load employees.'}}
async function addEmployee(employee:any){saving.value=true;try{await $fetch('/api/attendance/dtr/'+props.dtr.BatchID+'/employees',{method:'POST',body:{EmployeeID:employee.EmployeeID,DeploymentType:selectedType.value}});picker.value=false;await load();emit('changed')}catch(e:any){error.value=e?.data?.statusMessage||'Unable to add employee.'}finally{saving.value=false}}
async function updateType(row:Row,event:Event){const deploymentType=(event.target as HTMLSelectElement).value==='Reliever'?'Reliever':'Regular';typeSaving.value=row.EmployeeID;error.value='';try{await $fetch('/api/attendance/dtr/'+props.dtr.BatchID+'/employees',{method:'PUT',body:{EmployeeID:row.EmployeeID,DeploymentType:deploymentType}});await load();emit('changed')}catch(e:any){error.value=e?.data?.statusMessage||'Unable to update attendance type.';await load()}finally{typeSaving.value=null}}
function openBatch(row:Row){batchEmployee.value=row;batchShift.value='';batchShiftSearch.value='';batchSuggestionsOpen.value=false;batchOpen.value=true}
function selectBatchShift(shift:Shift){batchShift.value=String(shift.ShiftCodeID);batchShiftSearch.value=shift.ShiftCode+' — '+shift.ShiftName;batchSuggestionsOpen.value=false}
function batchAttendanceBody(row:Row,shift:Shift,attendanceDate:string){const inTime=String(shift.TimeIn).slice(0,5),outTime=String(shift.TimeOut).slice(0,5),outDate=new Date(attendanceDate+'T'+outTime);if(outTime<=inTime)outDate.setDate(outDate.getDate()+1);const body:any={...blankDay(row,attendanceDate),ShiftCodeID:shift.ShiftCodeID,AttendanceStatus:'Present',TimeIn:attendanceDate+'T'+inTime,TimeOut:outDate.getFullYear()+'-'+String(outDate.getMonth()+1).padStart(2,'0')+'-'+String(outDate.getDate()).padStart(2,'0')+'T'+outTime};body.RegularHours=Number(shift.RegularHours||0);body.OTHours=Number(shift.RegularOTCap||0);body.NightDiffHours=nightDiffHours(body.TimeIn,body.TimeOut,shift);return body}
async function applyBatch(){const row=batchEmployee.value,shift=selectedBatchShift.value;if(!row||!shift)return;saving.value=true;error.value='';try{await Promise.all(dates().map(attendanceDate=>$fetch('/api/attendance/dtr/'+props.dtr.BatchID+'/records',{method:'POST',body:batchAttendanceBody(row,shift,attendanceDate)})));batchOpen.value=false;await load();emit('changed')}catch(e:any){error.value=e?.data?.statusMessage||'Unable to replace the cutoff attendance.'}finally{saving.value=false}}
function openDay(row:Row,date:string){selectedRow.value=row;const current=entry(row,date);dayForm.value={...blankDay(row,date),...(current||{}),AttendanceDate:date,TimeIn:toInputDateTime(current?.TimeIn),TimeOut:toInputDateTime(current?.TimeOut),LateMinutes:Math.round(Number(current?.LateHours||0)*60),UndertimeMinutes:Math.round(Number(current?.UndertimeHours||0)*60)};dayOpen.value=true}
function refreshNightDiff(){const form=dayForm.value,shift=shifts.value.find(item=>String(item.ShiftCodeID)===String(form?.ShiftCodeID));if(form)form.NightDiffHours=shift?nightDiffHours(form.TimeIn,form.TimeOut,shift):0}
function adjustTimeOutFromHours(){const form=dayForm.value,shift=shifts.value.find(item=>String(item.ShiftCodeID)===String(form?.ShiftCodeID));if(!form||!shift||!form.TimeIn)return;const start=new Date(String(form.TimeIn).replace(' ','T')),regular=Number(form.RegularHours||0),ot=Number(form.OTHours||0),extension=Number(form.OTExtHours||0),total=regular+ot+extension;if(Number.isNaN(start.getTime())||!Number.isFinite(total)||total<0)return;const end=new Date(start.getTime()+Math.round(total*60)*60000);form.TimeOut=end.getFullYear()+'-'+String(end.getMonth()+1).padStart(2,'0')+'-'+String(end.getDate()).padStart(2,'0')+' '+String(end.getHours()).padStart(2,'0')+':'+String(end.getMinutes()).padStart(2,'0');refreshNightDiff()}
function applyShift(){const form=dayForm.value;if(!form)return;const shift=shifts.value.find(item=>String(item.ShiftCodeID)===String(form.ShiftCodeID));if(!shift)return;form.RegularHours=Number(shift.RegularHours||0);form.OTHours=Number(shift.RegularOTCap||0);const inTime=String(shift.TimeIn).slice(0,5),outTime=String(shift.TimeOut).slice(0,5);form.TimeIn=form.AttendanceDate+'T'+inTime;const outDate=new Date(form.AttendanceDate+'T'+outTime);if(outTime<=inTime)outDate.setDate(outDate.getDate()+1);form.TimeOut=outDate.getFullYear()+'-'+String(outDate.getMonth()+1).padStart(2,'0')+'-'+String(outDate.getDate()).padStart(2,'0')+'T'+outTime;refreshNightDiff()}
function clearNonWorkAttendance(){const form=dayForm.value;if(!form||!['Absent','Rest Day','On-Leave'].includes(form.AttendanceStatus))return;form.ShiftCodeID='';form.TimeIn='';form.TimeOut='';hourFields.forEach(([key])=>form[key]=0);form.LateHours=0;form.UndertimeHours=0;form.LateMinutes=0;form.UndertimeMinutes=0}
watch(()=>[dayForm.value?.RegularHours,dayForm.value?.OTHours,dayForm.value?.OTExtHours],()=>adjustTimeOutFromHours())
async function saveDay(){if(!dayForm.value)return;saving.value=true;error.value='';try{const body={...dayForm.value,LateHours:Number(dayForm.value.LateMinutes||0)/60,UndertimeHours:Number(dayForm.value.UndertimeMinutes||0)/60};delete body.LateMinutes;delete body.UndertimeMinutes;await $fetch('/api/attendance/dtr/'+props.dtr.BatchID+'/records',{method:'POST',body});dayOpen.value=false;await load();emit('changed')}catch(e:any){error.value=e?.data?.statusMessage||'Unable to save attendance.'}finally{saving.value=false}}
onMounted(load)
</script>

<template>
  <div class="dtr-attendance-layer">
    <section class="workspace">
      <button class="close" @click="emit('close')">x</button>
      <header><p>SUMMARY DAILY TIME RECORD</p><h2>{{ dtr.ClientName }} - {{ dtr.SiteName }}</h2><span>Payroll period: {{ dayLabel(dtr.PeriodStart) }} to {{ dayLabel(dtr.PeriodEnd) }}</span></header>
      <div class="toolbar"><input v-model.trim="search" placeholder="Search employee ID, number, or name"><button class="secondary" @click="applied=search">Search</button><button class="primary" @click="picker=true;findEmployees()">+ Add employee</button></div>
      <p class="hint">Click any day cell to add or update that employee's attendance for that date.</p><p v-if="error" class="error">{{error}}</p>
      <div class="table-wrap"><table class="cutoff-table"><thead><tr><th class="row-number" rowspan="2">No.</th><th class="person" rowspan="2">Name of personnel</th><th rowspan="2">Position</th><th rowspan="2">Type</th><th rowspan="2">Shift</th><th v-for="(date,index) in dates()" :key="date" class="day-head">{{index+1}}</th><th rowspan="2">Total days</th><th v-for="field in summaryFields" :key="field[0]" rowspan="2">{{field[1]}}</th></tr><tr><th v-for="date in dates()" :key="date+'-hours'" class="day-hours">HRS</th></tr></thead>
        <tbody><tr v-for="(row,index) in visibleRows" :key="row.EmployeeID"><td>{{index+1}}</td><td class="person"><strong>{{row.EmployeeName}}</strong><small>EMP-{{String(row.EmployeeID).padStart(4,'0')}} / {{row.EmployeeNumber||'No employee no.'}}</small></td><td>{{row.PositionName||'-'}}</td><td><select class="type-select" :value="row.DeploymentType" :disabled="typeSaving===row.EmployeeID" @change="updateType(row,$event)"><option>Regular</option><option>Reliever</option></select></td><td class="shift-tag">{{shiftTag(row)}}<button class="batch-plus" title="Apply one shift to all cutoff days" @click="openBatch(row)">+</button></td><td v-for="date in dates()" :key="date" class="day-cell"><button @click="openDay(row,date)"><strong>{{cellText(entry(row,date))}}</strong><small>{{cellSub(entry(row,date))}}</small></button></td><td>{{totalDays(row)}}</td><td v-for="field in summaryFields" :key="field[0]">{{formatNumber(row[field[0]])}}</td></tr><tr v-if="!rows.length"><td :colspan="6+dates().length+summaryFields.length" class="empty">No employee has been added to this DTR yet.</td></tr></tbody>
        <tfoot v-if="rows.length"><tr><th :colspan="5+dates().length">TOTAL</th><th>{{attendanceRows.filter(item=>String(item.AttendanceStatus)!=='Absent').length}}</th><th v-for="field in summaryFields" :key="field[0]">{{formatNumber(totals[field[0]])}}</th></tr></tfoot>
      </table></div>
    </section>
    <div v-if="picker" class="layer" @click.self="picker=false"><section class="modal employee-modal"><button class="close" @click="picker=false">x</button><h3>Add employee to this DTR</h3><p>Only employees under the DTR agency with an active rate for this client are shown.</p><div class="picker-tools"><input v-model.trim="employeeSearch" placeholder="Search employee ID, number, or name" @keyup.enter="findEmployees"><button class="secondary" @click="findEmployees">Search</button><select v-model="selectedType"><option>Regular</option><option>Reliever</option></select></div><div class="employee-list"><button v-for="employee in employees" :key="employee.EmployeeID" @click="addEmployee(employee)"><strong>EMP-{{String(employee.EmployeeID).padStart(4,'0')}} - {{employee.EmployeeName}}</strong><span>{{employee.EmployeeNumber||'No employee no.'}} / {{employee.PositionName}} / add as {{selectedType}}</span></button><p v-if="!employees.length">No eligible employee found for this client/site DTR.</p></div></section></div>
    <div v-if="batchOpen&&batchEmployee" class="layer" @click.self="batchOpen=false"><form class="modal batch-modal" @submit.prevent="applyBatch"><button class="close" type="button" @click="batchOpen=false">x</button><h3>Apply shift to cutoff</h3><p><strong>{{batchEmployee.EmployeeName}}</strong><br>Select one existing shift for this DTR agency to replace every day from {{dayLabel(dtr.PeriodStart)}} to {{dayLabel(dtr.PeriodEnd)}}.</p><label>Search shift code or name<div class="shift-combobox"><input v-model.trim="batchShiftSearch" type="search" autocomplete="off" placeholder="e.g. DS0700-1900 or Night shift" @focus="batchSuggestionsOpen=true" @input="batchShift='';batchSuggestionsOpen=true"><div v-if="batchSuggestionsOpen" class="shift-suggestions"><button v-for="shift in visibleBatchShifts" :key="shift.ShiftCodeID" type="button" @mousedown.prevent="selectBatchShift(shift)"><strong>{{shift.ShiftCode}}</strong><span>{{shift.ShiftName}} · {{shift.ShiftType}} · {{formatNumber(shift.RegularHours)}} / {{formatNumber(shift.RegularOTCap)}}</span></button><p v-if="!visibleBatchShifts.length">No matching active shift code for {{ dtr.AgencyName }}.</p></div></div></label><p v-if="selectedBatchShift" class="selected-shift">Selected: <strong>{{selectedBatchShift.ShiftCode}}</strong> — {{formatNumber(selectedBatchShift.RegularHours)}} regular / {{formatNumber(selectedBatchShift.RegularOTCap)}} OT for {{dates().length}} days.</p><p class="hint">Applying a shift always replaces this employee's shift, time in/out, regular hours, and OT for every day in this cutoff. You can still edit one day afterward.</p><p v-if="error" class="error">{{error}}</p><footer><button class="secondary" type="button" @click="batchOpen=false">Cancel</button><button class="primary" type="submit" :disabled="saving||!batchShift">{{saving?'Applying...':'Apply shift to all days'}}</button></footer></form></div>
    <div v-if="dayOpen&&dayForm&&selectedRow" class="layer" @click.self="dayOpen=false"><form class="modal attendance-modal" @submit.prevent="saveDay"><button class="close" type="button" @click="dayOpen=false">x</button><h3>Attendance input</h3><p><strong>EMP-{{String(selectedRow.EmployeeID).padStart(4,'0')}} - {{selectedRow.EmployeeName}}</strong><br>{{dayLabel(dayForm.AttendanceDate)}} / {{dtr.ClientName}} - {{dtr.SiteName}}</p><div class="day-grid"><label>Shift code<select v-model="dayForm.ShiftCodeID" @change="applyShift"><option value="">No shift / manual</option><option v-for="shift in shifts" :key="shift.ShiftCodeID" :value="shift.ShiftCodeID">{{shift.ShiftCode}} - {{shift.ShiftName}} ({{shift.ShiftType}})</option></select></label><label>Status<select v-model="dayForm.AttendanceStatus" @change="clearNonWorkAttendance"><option>Present</option><option>Absent</option><option>Late</option><option>Half-Day</option><option>On-Leave</option><option>Holiday</option><option>Rest Day</option></select></label><label>Time in<input v-model.trim="dayForm.TimeIn" type="text" inputmode="numeric" placeholder="YYYY-MM-DD HH:mm"></label><label>Time out<input v-model.trim="dayForm.TimeOut" type="text" inputmode="numeric" placeholder="YYYY-MM-DD HH:mm"></label><label v-for="field in hourFields" :key="field[0]">{{field[1]}}<input v-model.number="dayForm[field[0]]" type="number" min="0" max="24" step="0.25"></label><label>Late (minutes)<input v-model.number="dayForm.LateMinutes" type="number" min="0" max="1440" step="1" placeholder="e.g. 15"></label><label>Undertime (minutes)<input v-model.number="dayForm.UndertimeMinutes" type="number" min="0" max="1440" step="1" placeholder="e.g. 30"></label><label class="remarks">Remarks<textarea v-model.trim="dayForm.Remarks" maxlength="255"></textarea></label></div><p v-if="error" class="error">{{error}}</p><footer><button class="secondary" type="button" @click="dayOpen=false">Cancel</button><button class="primary" :disabled="saving">{{saving?'Saving...':'Save attendance'}}</button></footer></form></div>
  </div>
</template>

<style>
.dtr-attendance-layer{position:fixed;z-index:60;inset:0;background:rgba(14,28,55,.55);padding:18px}.dtr-attendance-layer .workspace{position:relative;height:100%;box-sizing:border-box;padding:28px;background:#f8faff;border-radius:16px;overflow:auto}.dtr-attendance-layer .close{position:absolute;right:20px;top:13px;border:0;background:transparent;font-size:26px;cursor:pointer;color:#12345d}.dtr-attendance-layer header p{margin:0 0 7px;color:#4975bd;font-size:12px;font-weight:800;letter-spacing:.08em}.dtr-attendance-layer h2,.dtr-attendance-layer h3{margin:0;color:#112f5c}.dtr-attendance-layer header span,.dtr-attendance-layer .modal>p{display:block;margin-top:7px;color:#64738d}.dtr-attendance-layer .toolbar,.dtr-attendance-layer .picker-tools{display:flex;gap:10px;margin:24px 0 12px}.dtr-attendance-layer .toolbar input,.dtr-attendance-layer .picker-tools input{width:min(560px,100%)}.dtr-attendance-layer input,.dtr-attendance-layer select,.dtr-attendance-layer textarea{box-sizing:border-box;min-height:42px;border:1px solid #cfdaeb;border-radius:8px;background:#fff;color:#1f3b66;font:inherit;padding:0 12px}.dtr-attendance-layer textarea{min-height:74px;padding:10px}.dtr-attendance-layer .primary,.dtr-attendance-layer .secondary{border:1px solid #d4deed;border-radius:8px;padding:10px 14px;background:#fff;color:#1d4bcb;font:inherit;font-weight:700;cursor:pointer}.dtr-attendance-layer .primary{background:#2867d8;border-color:#2867d8;color:#fff}.dtr-attendance-layer .hint{margin:0 0 14px;color:#60718f}.dtr-attendance-layer .error{color:#b42318}.dtr-attendance-layer .table-wrap{overflow:auto;border:1px solid #dce5f1;border-radius:12px;background:#fff}.dtr-attendance-layer .cutoff-table{border-collapse:collapse;min-width:2350px;width:max-content}.dtr-attendance-layer .cutoff-table th,.dtr-attendance-layer .cutoff-table td{border:1px solid #b9c0c7;padding:9px 11px;text-align:center;white-space:nowrap}.dtr-attendance-layer .cutoff-table thead th{background:#fff700;color:#101820;font-size:12px;text-transform:uppercase}.dtr-attendance-layer .cutoff-table th small,.dtr-attendance-layer .cutoff-table td small{display:block;margin-top:4px;font-size:11px}.dtr-attendance-layer .cutoff-table .row-number{min-width:34px}.dtr-attendance-layer .cutoff-table .person{min-width:240px;text-align:left}.dtr-attendance-layer .cutoff-table .person small{color:#536987}.dtr-attendance-layer .cutoff-table .day-head{min-width:54px}.dtr-attendance-layer .cutoff-table .day-cell{padding:0;min-width:78px}.dtr-attendance-layer .day-cell button{display:block;box-sizing:border-box;width:100%;min-height:67px;border:0;background:#fff;color:#142f58;padding:7px;cursor:pointer}.dtr-attendance-layer .day-cell button:hover{background:#edf4ff}.dtr-attendance-layer .day-cell small{color:#526b91;white-space:normal}.dtr-attendance-layer .shift-tag{font-weight:800;color:#1947cb}.dtr-attendance-layer tfoot th{background:#c6dfb5;color:#132919}.dtr-attendance-layer .empty{padding:40px!important;color:#6b7b92}.dtr-attendance-layer .layer{position:fixed;z-index:70;inset:0;display:grid;place-items:center;padding:20px;background:rgba(14,28,55,.6)}.dtr-attendance-layer .modal{position:relative;box-sizing:border-box;width:min(820px,100%);max-height:90vh;overflow:auto;padding:28px;background:#fff;border-radius:15px}.dtr-attendance-layer .employee-list{border:1px solid #dce5f1;border-radius:9px;overflow:auto;max-height:420px}.dtr-attendance-layer .employee-list button{display:block;width:100%;border:0;border-bottom:1px solid #e4ebf5;background:#fff;padding:14px;text-align:left;cursor:pointer}.dtr-attendance-layer .employee-list button:hover{background:#f1f5ff}.dtr-attendance-layer .employee-list span{display:block;margin-top:5px;color:#63738d;font-size:13px}.dtr-attendance-layer .employee-list p{padding:12px;color:#718099}.dtr-attendance-layer .attendance-modal{width:min(1080px,100%)}.dtr-attendance-layer .day-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:18px}.d